#include <stdio.h>

int main() {
    int a[6] = {10, 20, 30, 40, 50, 60};
    int IX = 0;                 /* 变址寄存器，从 0 开始，每次 +4（字长） */
    int base = 1000;            /* 模拟基址，仅用于演示 EA 计算 */

    printf("数组 a 首地址(模拟) = %d\n", base);
    for (int i = 0; i < 6; i++) {
        int EA = base + IX;     /* 变址寻址：EA = 基址 + (IX) */
        printf("i=%d  IX=%d  EA=%d  取数=%d\n", i, IX, EA, a[i]);
        IX += 4;                /* 变址寄存器自增，遍历数组元素 */
    }
    return 0;
}
